(()=>{
'use strict';
const SUPABASE_URL='https://ciqzrrpsnhbsqafpbdsu.supabase.co';
const SUPABASE_KEY='sb_publishable_L_KJL0I0Xzu9Mdt8mYGPVw_LvbjICBM';
const db=window.supabase.createClient(SUPABASE_URL,SUPABASE_KEY);
const $=s=>document.querySelector(s);
function esc(v=''){return String(v).replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[m]))}
function toast(msg,err=false){const t=$('#toast');if(!t)return;t.textContent=msg;t.classList.remove('hidden');t.style.borderColor=err?'#71323a':'#353d46';clearTimeout(window.__toast);window.__toast=setTimeout(()=>t.classList.add('hidden'),3500)}
function initials(name='U'){return name.split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase()||'U'}
async function loadProfile(uid){const r=await db.from('fitpro_profiles').select('*').eq('id',uid).single();if(r.error)throw r.error;return r.data}
async function loadWorkouts(uid){const r=await db.from('fitpro_workouts').select('*,fitpro_exercises(*)').eq('student_id',uid).order('scheduled_for');if(r.error)throw r.error;return r.data||[]}
async function loadLatestPrescription(uid){const r=await db.from('fitpro_ai_prescriptions').select('*').eq('student_id',uid).order('created_at',{ascending:false}).limit(1).maybeSingle();if(r.error)throw r.error;return r.data}
async function loadMeasurements(uid){const r=await db.from('fitpro_measurements').select('*').eq('student_id',uid).order('measured_at',{ascending:false}).limit(20);if(r.error)throw r.error;return r.data||[]}
let state={session:null,profile:null,workouts:[],prescription:null,measurements:[],tab:'home'};
const app=$('#app');
const today=()=>new Intl.DateTimeFormat('pt-BR',{weekday:'short',day:'2-digit',month:'short'}).format(new Date()).replace('.','');
function authView(){app.innerHTML=`<div class="auth"><div class="authCard"><div class="authBrand"><div class="logo">FP</div><div><b>FITPRO</b><div class="muted" style="font-size:11px">PERSONAL TRAINER ONLINE</div></div></div><h1>Seu treino evolui com você.</h1><p class="muted">Treinos personalizados, acompanhamento inteligente e progressão em um único lugar.</p><form id="auth" class="form"><input id="name" placeholder="Nome completo (no cadastro)"><input id="email" type="email" placeholder="E-mail" required><input id="pass" type="password" minlength="6" placeholder="Senha" required><div class="actions"><button class="btn primary" data-mode="login">Entrar</button><button class="btn ghost" data-mode="signup">Criar conta</button></div></form><div class="authNote">Seus dados de treino ficam protegidos na sua conta.</div></div></div>`;document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=async e=>{e.preventDefault();const mode=b.dataset.mode,email=$('#email').value,password=$('#pass').value,name=$('#name').value.trim();if(mode==='login'){const r=await db.auth.signInWithPassword({email,password});if(r.error)toast(r.error.message,true)}else{const r=await db.auth.signUp({email,password,options:{data:{full_name:name}}});if(r.error)return toast(r.error.message,true);if(r.data.user){await db.from('fitpro_profiles').upsert({id:r.data.user.id,full_name:name||email.split('@')[0],role:'student'});toast('Conta criada!')}}})}
async function refresh(){state.profile=await loadProfile(state.session.user.id);state.workouts=await loadWorkouts(state.session.user.id);state.prescription=await loadLatestPrescription(state.session.user.id);state.measurements=await loadMeasurements(state.session.user.id)}
function shell(content){const p=state.profile||{};app.innerHTML=`<div class="shell"><header class="top"><div class="brand"><div class="logo">FP</div><div class="brandMeta"><b>FITPRO</b><small class="muted">Personal Online</small></div></div><div class="avatar">${initials(p.full_name||'U')}</div></header><main>${content}</main><nav class="nav"><button data-tab="home" class="${state.tab==='home'?'active':''}"><span class="navIcon">⌂</span><span>Início</span></button><button data-tab="treinos" class="${state.tab==='treinos'?'active':''}"><span class="navIcon">◫</span><span>Treinos</span></button><button data-tab="progresso" class="${state.tab==='progresso'?'active':''}"><span class="navIcon">↗</span><span>Progresso</span></button><button data-tab="perfil" class="${state.tab==='perfil'?'active':''}"><span class="navIcon">●</span><span>Perfil</span></button></nav></div>`;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;render()})}
function home(){const next=state.workouts.find(w=>!w.completed_at),done=state.workouts.filter(w=>w.completed_at).length,total=state.workouts.length,ratio=total?Math.round(done/total*100):0;return `<div class="greeting"><div><h1>Olá, ${esc((state.profile?.full_name||'atleta').split(' ')[0])} 👋</h1><p class="muted">Pronto para evoluir hoje?</p></div><div class="day">${today()}</div></div><div class="hero"><span class="eyebrow">${next?'Treino de hoje':'Plano inteligente'}</span><h1>${next?esc(next.title):'Seu plano começa aqui'}</h1><p class="muted">${next?esc(next.focus||'Sessão personalizada pela sua avaliação'):'Responda sua avaliação e receba uma ficha personalizada automaticamente.'}</p><div class="actions">${next?'<button class="btn primary" id="start">▶ Iniciar treino</button>':'<button class="btn primary" id="assessment">Começar avaliação</button>'}</div></div><div class="section"><div class="sectionHead"><h2>Seu ritmo</h2><span>${ratio}% concluído</span></div><div class="grid"><div class="card stat"><span class="muted">Treinos feitos</span><strong>${done}</strong><small>${total?total-done+' restantes no ciclo':'aguardando plano'}</small></div><div class="card stat"><span class="muted">Plano atual</span><strong>${state.prescription?'Ativo':'—'}</strong><small>personalizado pela IA</small></div></div></div>`}
function workoutsView(){return `<div class="greeting"><div><h1>Meus treinos</h1><p class="muted">Sua rotina organizada por sessão.</p></div><div class="day">${state.workouts.length} sessões</div></div>${state.workouts.length?state.workouts.map(w=>`<div class="workout"><div class="workoutRow"><div class="workoutIcon">${w.completed_at?'✓':'🏋'}</div><div class="workoutMain"><span class="tag">${w.completed_at?'Concluído':'Programado'}</span><h3>${esc(w.title)}</h3><p class="muted">${esc(w.focus||'Treino personalizado')} • ${w.estimated_minutes||60} min</p></div></div><div class="actions"><button class="btn ${w.completed_at?'ghost':'primary'}" data-workout="${w.id}">${w.completed_at?'Ver treino':'Iniciar sessão'}</button></div></div>`).join(''):'<div class="card"><h3>Nenhum treino ainda</h3><p class="muted">Faça sua avaliação para a IA montar seu programa.</p><button id="assessment" class="btn primary">Fazer avaliação</button></div>'}`}
function progress(){const m=state.measurements[0],done=state.workouts.filter(w=>w.completed_at).length,total=state.workouts.length,ratio=total?Math.min(100,Math.round(done/total*100)):0;return `<div class="greeting"><div><h1>Progresso</h1><p class="muted">Consistência que vira resultado.</p></div></div><div class="card progressHero"><div><span class="muted">Conclusão do ciclo</span><div class="bigNumber">${ratio}%</div></div></div><div class="grid"><div class="card stat"><span class="muted">Peso</span><strong>${m?.weight_kg?m.weight_kg+' kg':'—'}</strong></div><div class="card stat"><span class="muted">Treinos</span><strong>${done}</strong></div></div>`}
function profile(){return `<div class="greeting"><div><h1>Perfil</h1><p class="muted">Conta, objetivo e preferências.</p></div></div><div class="card profileCard"><div class="profileAvatar">${initials(state.profile?.full_name||'U')}</div><h2>${esc(state.profile?.full_name||'Aluno')}</h2><p class="muted">Aluno FITPRO</p></div><div class="actions"><button id="assessment" class="btn ghost">Refazer avaliação</button><button id="logout" class="btn danger">Sair</button></div>`}
function assessmentView(){app.innerHTML=`<div class="auth"><div class="authCard"><span class="eyebrow">FITPRO AI</span><h1>Avaliação inteligente</h1><p class="muted">Preencha os dados principais para gerar seu plano.</p><div class="form"><select id="goal"><option value="hipertrofia">Ganhar massa muscular</option><option value="emagrecimento">Emagrecer / recomposição</option><option value="forca">Força</option></select><select id="level"><option value="iniciante">Iniciante</option><option value="intermediario">Intermediário</option><option value="avancado">Avançado</option></select><select id="days"><option value="3">3x por semana</option><option value="4">4x por semana</option><option value="5">5x por semana</option></select><input id="minutes" type="number" value="60" placeholder="Minutos por treino"><textarea id="injuries" placeholder="Lesões ou limitações"></textarea><button id="generate" class="btn primary">✦ Gerar meu plano</button><button id="cancelAssessment" class="btn ghost">Voltar</button></div></div></div>`;$('#cancelAssessment').onclick=render;$('#generate').onclick=async()=>{const payload={student_id:state.session.user.id,status:'submitted',consent:true,goal:$('#goal').value,experience_level:$('#level').value,training_days:+$('#days').value,session_minutes:+$('#minutes').value||60,injuries:$('#injuries').value,answers:{version:7}};app.innerHTML='<div class="loadingScreen"><div class="loadingCard"><div class="loaderOrb"></div><h2>Criando seu plano</h2><p class="muted">Analisando sua avaliação...</p></div></div>';try{const a=await db.from('fitpro_assessments').insert(payload).select().single();if(a.error)throw a.error;const fn=await db.functions.invoke('fitpro-analyze-assessment',{body:{assessment_id:a.data.id,publish:true}});if(fn.error)throw fn.error;await refresh();state.tab='home';toast('Plano criado com sucesso!');render()}catch(e){toast(e.message||String(e),true);render()}}}
function workoutDetail(w){const ex=w.fitpro_exercises||[];app.innerHTML=`<div class="shell"><main><button id="back" class="btn ghost">← Voltar</button><h1>${esc(w.title)}</h1>${ex.map(x=>`<div class="exercise"><h3>${esc(x.name)}</h3><p class="muted">${x.sets} séries • ${esc(x.reps)} reps • RIR ${x.target_rir??2}</p></div>`).join('')}</main></div>`;$('#back').onclick=render}
function bind(){$('#assessment')?.addEventListener('click',assessmentView);$('#start')?.addEventListener('click',()=>{const next=state.workouts.find(w=>!w.completed_at);if(next)workoutDetail(next)});document.querySelectorAll('[data-workout]').forEach(b=>b.onclick=()=>workoutDetail(state.workouts.find(w=>String(w.id)===b.dataset.workout)));$('#logout')?.addEventListener('click',async()=>{await db.auth.signOut();state={session:null,profile:null,workouts:[],prescription:null,measurements:[],tab:'home'};authView()})}
function render(){if(!state.session)return authView();shell(state.tab==='home'?home():state.tab==='treinos'?workoutsView():state.tab==='progresso'?progress():profile());bind()}
async function boot(session){state.session=session;if(!session)return render();try{await refresh()}catch(e){console.error(e);state.profile={full_name:session.user?.user_metadata?.full_name||session.user?.email?.split('@')[0]||'Aluno',role:'student'};state.workouts=[];state.measurements=[]}render()}
db.auth.onAuthStateChange((_e,s)=>boot(s));db.auth.getSession().then(r=>boot(r.data.session));
window.FITPRO_READY=true;
})();